"""The ``pennywise`` command line."""

import argparse
import csv
import datetime
import io
import json
import re
import sys
from typing import List, Optional

from . import reports
from .ledger import Entry, ParseError, format_amount, format_entry, parse

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


class _Failure(Exception):
    """Internal: stop with ``code`` after printing ``message`` on stderr."""

    def __init__(self, code: int, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def _date_arg(text: str) -> datetime.date:
    if _DATE_RE.fullmatch(text):
        try:
            return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise",
        description="Read a plain-text household ledger and report where the money went.",
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="list entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger file")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print the entries in another format")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_ledger(path: str) -> List[Entry]:
    try:
        if path == "-":
            stream = sys.stdin
            raw = getattr(stream, "buffer", None)
            text = raw.read().decode("utf-8-sig") if raw is not None else stream.read()
        else:
            with open(path, "rb") as handle:
                text = handle.read().decode("utf-8-sig")
    except (OSError, UnicodeDecodeError) as exc:
        name = "standard input" if path == "-" else path
        raise _Failure(2, "cannot read %s: %s" % (name, getattr(exc, "strerror", None) or exc))
    try:
        return parse(text)
    except ParseError as exc:
        raise _Failure(1, str(exc))


def _sorted_entries(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same day keeps file order


def _entry_json(entry: Entry) -> dict:
    return {
        "date": entry.date.isoformat(),
        "category": entry.category,
        "amount": format_amount(entry.amount),
        "note": entry.note,
    }


def _lines(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def _cmd_balance(args) -> str:
    total = format_amount(reports.balance(_read_ledger(args.file)))
    if args.json:
        return json.dumps({"balance": total}) + "\n"
    return total + "\n"


def _cmd_summary(args) -> str:
    entries = _read_ledger(args.file)
    totals = reports.by_month(entries) if args.by == "month" else reports.by_category(entries)
    formatted = {name: format_amount(totals[name]) for name in sorted(totals)}
    if args.json:
        return json.dumps(formatted) + "\n"
    return _lines(["%s  %s" % item for item in formatted.items()])


def _cmd_list(args) -> str:
    entries = _read_ledger(args.file)
    entries = _sorted_entries(
        reports.filter_entries(entries, args.category, args.since, args.until)
    )
    if args.json:
        return json.dumps([_entry_json(e) for e in entries]) + "\n"
    return _lines([format_entry(e) for e in entries])


def _cmd_export(args) -> str:
    entries = _sorted_entries(_read_ledger(args.file))
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        row = _entry_json(e)
        writer.writerow([row["date"], row["category"], row["amount"], row["note"]])
    return buffer.getvalue()


def _cmd_add(args) -> str:
    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch.isspace() for ch in value):
            raise _Failure(1, "line 1: invalid %s %r" % (label, value))
    if "\n" in args.note or "\r" in args.note:
        raise _Failure(1, "line 1: note must not contain a newline")
    try:
        parsed = parse("%s %s %s %s" % (args.date, args.category, args.amount, args.note))
    except ParseError as exc:
        raise _Failure(1, str(exc))
    line = format_entry(parsed[0])

    try:
        prefix = ""
        try:
            with open(args.file, "rb") as handle:
                handle.seek(0, 2)
                if handle.tell() > 0:
                    handle.seek(-1, 2)
                    if handle.read(1) != b"\n":
                        prefix = "\n"
        except FileNotFoundError:
            pass
        with open(args.file, "ab") as handle:
            handle.write((prefix + line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Failure(2, "cannot write %s: %s" % (args.file, exc.strerror or exc))
    return line + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv: Optional[List[str]] = None) -> int:
    """Run the command line; return the exit status (0, 1 or 2)."""
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        output = _COMMANDS[args.command](args)
    except _Failure as failure:
        sys.stderr.write("pennywise: %s\n" % failure.message)
        return failure.code
    sys.stdout.write(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())
